import type { Metadata } from "next";

/**
 * Next replaces (not merges) a page's `openGraph` object over the layout's, so the
 * shared fields live here and are spread into both the layout and every page.
 */
export const openGraphBase = {
  type: "website",
  siteName: "Sari Sari Design",
} as const;

// The card generated by app/opengraph-image.tsx. Next only auto-attaches it to the
// root route, so nested pages that override openGraph/twitter reference it explicitly.
const image = { url: "/opengraph-image", width: 1200, height: 630, alt: "Sari Sari — Your fractional product team." };

/** Per-page SEO + link-preview metadata; the layout's title template adds the site suffix. */
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { ...openGraphBase, title, description, url: path, images: [image] },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}
